{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 청년 기본 조례상 청년 건강 지원이 취업이 안 되고 생활비가 빠듯한 형편을 우선 고려하는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 청년 기본 조례 제18조 제1항은 시장이 청년의 신체적·정신적 건강을 보호·증진하기 위한 방안을 강구하여야 하며 예산의 범위에서 지원을 할 수 있다고 정하고, 이 경우 사회·경제적 이유 등으로 건강관리에 어려움을 겪는 청년을 우선적으로 고려하여야 한다고 규정한다. 취업이 안 되고 생활비가 빠듯한 형편은 사회·경제적 이유 등으로 건강관리에 어려움을 겪는 경우에 해당할 수 있으므로, 그러한 요건을 충족하면 우선 고려 대상이 될 수 있다. 다만 우선 고려의 구체적 기준·대상 선정 방법 등은 조례에 직접 정해져 있지 않다.",
          "b_ids": "청년:제18조제1항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
